def match(orders):
    import heapq

    book_buy = []   # heap of (-price, arrival, id) for resting buy limit orders
    book_sell = []  # heap of (price, arrival, id) for resting sell limit orders
    order_info = {}  # id -> [side, price, qty_remaining, arrival, status]
    trades = []
    arrival_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = order_info.get(oid)
            if info is not None and info[4] == 'active' and info[2] > 0:
                info[4] = 'cancelled'
            continue

        oid = o[1]
        side = o[2]

        if typ == 'market':
            qty = o[3]
            price = None
        else:
            price = o[3]
            qty = o[4]

        arrival = arrival_counter
        arrival_counter += 1

        order_info[oid] = [side, price, qty, arrival, 'active']

        opposite = book_sell if side == 'buy' else book_buy

        remaining = qty

        while remaining > 0:
            # clean up stale entries at top of opposite heap
            while opposite:
                top = opposite[0]
                top_id = top[2]
                top_info = order_info[top_id]
                if top_info[4] != 'active' or top_info[2] <= 0:
                    heapq.heappop(opposite)
                    continue
                break

            if not opposite:
                break

            top = opposite[0]
            top_id = top[2]
            top_info = order_info[top_id]
            top_price = top_info[1]

            if typ == 'market':
                match_ok = True
            else:
                if side == 'buy':
                    match_ok = price >= top_price
                else:
                    match_ok = price <= top_price

            if not match_ok:
                break

            trade_qty = min(remaining, top_info[2])
            trade_price = top_price

            if side == 'buy':
                trades.append([oid, top_id, trade_price, trade_qty])
            else:
                trades.append([top_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            top_info[2] -= trade_qty

            if top_info[2] == 0:
                top_info[4] = 'filled'
                heapq.heappop(opposite)
            # else: partially filled resting order keeps its place (still at top),
            # loop will re-check remaining and either continue matching or exit

        order_info[oid][2] = remaining

        if remaining > 0:
            if typ == 'limit':
                order_info[oid][4] = 'active'
                if side == 'buy':
                    heapq.heappush(book_buy, (-price, arrival, oid))
                else:
                    heapq.heappush(book_sell, (price, arrival, oid))
            else:
                # ioc or market: discard remainder
                order_info[oid][4] = 'filled'
        else:
            order_info[oid][4] = 'filled'

    return trades

